# Let's try to get more edges by being smarter about adding edges.
# We can also try to add edges between existing vertices.

import random

def has_cycle_of_length_at_most(adj, max_len):
    n = len(adj)
    for s in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[s] = 0
        queue = [s]
        for u in queue:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u] and dist[u] + dist[v] + 1 <= max_len:
                    return True
    return False

def is_3_colorable(adj):
    n = len(adj)
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        used = set()
        for u in adj[v]:
            if colors[u] != -1:
                used.add(colors[u])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

def try_build_graph(target_edges=33, max_tries=10000):
    for attempt in range(max_tries):
        n = 30
        adj = [[] for _ in range(n)]

        # Start with a 7-cycle
        cycle = list(range(7))
        for i in range(7):
            adj[cycle[i]].append(cycle[(i+1)%7])
            adj[cycle[(i+1)%7]].append(cycle[i])

        # Add remaining vertices
        for v in range(7, n):
            candidates = list(range(v))
            random.shuffle(candidates)
            for u in candidates:
                adj[v].append(u)
                adj[u].append(v)
                if has_cycle_of_length_at_most(adj, 6):
                    adj[v].pop()
                    adj[u].pop()
                else:
                    break  # connected v to one vertex

        # Now try to add more edges between existing vertices
        # Get all possible non-edges
        possible = []
        for u in range(n):
            for v in range(u+1, n):
                if v not in adj[u]:
                    possible.append((u, v))
        random.shuffle(possible)

        for u, v in possible:
            adj[u].append(v)
            adj[v].append(u)
            if has_cycle_of_length_at_most(adj, 6):
                adj[u].pop()
                adj[v].pop()
            else:
                pass  # keep the edge

        edge_count = sum(len(a) for a in adj) // 2
        if edge_count >= target_edges:
            if not has_cycle_of_length_at_most(adj, 6):
                if is_3_colorable(adj):
                    edges = [(u, v) for u in range(n) for v in adj[u] if u < v]
                    return edges, adj, edge_count
    return None, None, 0

edges, adj, cnt = try_build_graph(33, 5000)
print(f"Found: {edges is not None}, edges: {cnt}")
if edges:
    print(f"Edges: {sorted(edges)}")

