# Check girth >= 7
def shortest_cycle(adj):
    n = len(adj)
    min_cycle = n + 1
    for s in range(n):
        dist = [-1] * n
        parent = [-1] * n
        dist[s] = 0
        queue = [s]
        for u in queue:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

print(f"Girth (shortest cycle): {shortest_cycle(adj)}")

# Check 3-colorability
def is_3_colorable(adj):
    n = len(adj)
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        # Order by degree for efficiency
        used = set()
        for u in adj[v]:
            if colors[u] != -1:
                used.add(colors[u])
        for c in range(3):
            if c not in used:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

